 static void Surface(MeshFilter mf,WoodlandRoute b,Material mat,float begin,float end,bool lift=false){var mesh=Object.Instantiate(mf.sharedMesh);mesh.name=mf.name+" atmosphere";var v=mesh.vertices;var colors=new Color[v.Length];for(int i=0;i<v.Length;i++){var p=mf.transform.TransformPoint(v[i]);float s=b.Project(p,out _);if(lift&&(i%4==1||i%4==2)){p.y+=.9f*(1-Mathf.SmoothStep(0,1,(s-begin)/28));v[i]=mf.transform.InverseTransformPoint(p);}float portal=Mathf.Max(1-Mathf.Clamp01((s-begin)/20),1-Mathf.Clamp01((end-s)/26));float pocket=Mathf.Pow(Mathf.Max(0,Mathf.Cos((s-begin)*Mathf.PI/24)),12)*.17f;float value=Mathf.Lerp(.34f+pocket,1,portal);colors[i]=new(value,value,value,1);}mesh.vertices=v;mesh.colors=colors;mesh.RecalculateBounds();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,F+"/surface-"+(serial++)+".asset");mf.sharedMesh=mesh;mf.GetComponent<Renderer>().sharedMaterial=mat;var c=mf.GetComponent<MeshCollider>();if(c)c.sharedMesh=mesh;}
