 for(int i=0;i<4;i++){var p=b.At(b.undergroundStart+10+i*1.8f,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;int edge=i%2==0?1:-1;var rat=new GameObject("Scurrying drain rat "+(i+1)).transform;rat.SetParent(encounter.transform);rat.position=p+side*edge*(1.1f+i*.24f)+Vector3.up*.14f;rat.rotation=Quaternion.LookRotation(f);var save=root;root=rat;
