 var letters=new GameObject("LOGGING RIDGE",typeof(TextMesh));letters.transform.SetParent(root);letters.transform.SetPositionAndRotation(signP+Vector3.up*2.1f-rf*.08f,signQ);var text=letters.GetComponent<TextMesh>();text.text="LOGGING RIDGE";text.fontSize=56;text.characterSize=.09f;text.anchor=TextAnchor.MiddleCenter;text.alignment=TextAlignment.Center;text.color=new(1,.78f,.32f);var fontMat=new Material(text.GetComponent<Renderer>().sharedMaterial){shader=Shader.Find("Racer/SummitText")};AssetDatabase.CreateAsset(fontMat,F+"/Logging Ridge font.mat");text.GetComponent<Renderer>().sharedMaterial=fontMat;
