 var shellVertices=caveShell.sharedMesh.vertices.Select(caveShell.transform.TransformPoint).ToArray();float begin=shellVertices.Min(p=>b.Project(p,out _)),end=shellVertices.Max(p=>b.Project(p,out _));var rock=Mat("Dark damp cave stone",new(.43f,.39f,.33f),true,true);Surface(caveShell,b,rock,begin,end);var stone=Mat("Fallen cave stone",new(.17f,.16f,.125f));var roots=Mat("Cave exposed roots",new(.15f,.10f,.055f));var damp=Mat("Cave damp patches",new(.055f,.075f,.064f));damp.SetFloat("_Smoothness",.85f);
 foreach(var l in Object.FindObjectsByType<Light>().Where(l=>l.name=="Cave warm wayfinding")){l.intensity=.22f;l.range=12;l.color=new(.52f,.63f,.61f);}
 for(float s=begin+12;s<end-12;s+=7){var p=b.At(s,out var f);var side=Vector3.Cross(Vector3.up,f).normalized;var q=Quaternion.LookRotation(f);foreach(int edge in new[]{-1,1}){
 var foot=p+side*edge*4.7f;var ground=Physics.RaycastAll(foot+Vector3.up*3,Vector3.down,7,1,QueryTriggerInteraction.Ignore).Where(h=>h.collider.name.StartsWith("Ground_")).OrderBy(h=>Mathf.Abs(h.point.y-foot.y)).ToArray();if(ground.Length==0)continue;foot.y=ground[0].point.y;
 Part("Cave fallen angular stone",foot+Vector3.up*.18f,new(.7f,.36f,.95f),q*Quaternion.Euler(0,s*7,12),stone,PrimitiveType.Cube);
